package com.waypoint.planning.messaging;
import org.junit.jupiter.api.*;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.transaction.support.*;import java.time.*;import java.util.*;import static org.mockito.Mockito.*;
class PlanningEventPublisherTest {
 @AfterEach void cleanup(){if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.clearSynchronization();TransactionSynchronizationManager.setActualTransactionActive(false);}
 @Test void allocationEventIsSentOnlyAfterCommit(){RabbitTemplate rabbit=mock(RabbitTemplate.class);PlanningEventPublisher publisher=new PlanningEventPublisher(rabbit,"events");TransactionSynchronizationManager.setActualTransactionActive(true);TransactionSynchronizationManager.initSynchronization();publisher.allocationCompleted(UUID.randomUUID(),"VEH",List.of(UUID.randomUUID()),LocalDate.now());verifyNoInteractions(rabbit);TransactionSynchronizationManager.getSynchronizations().forEach(TransactionSynchronization::afterCommit);verify(rabbit,times(1)).convertAndSend(eq("events"),eq("allocation.completed"),any(Map.class));}
 @Test void deferralEventIsSentOnlyAfterCommit(){RabbitTemplate rabbit=mock(RabbitTemplate.class);PlanningEventPublisher publisher=new PlanningEventPublisher(rabbit,"events");TransactionSynchronizationManager.setActualTransactionActive(true);TransactionSynchronizationManager.initSynchronization();publisher.orderDeferred(UUID.randomUUID(),"reason","TEMP",LocalDate.now().plusDays(1));verifyNoInteractions(rabbit);TransactionSynchronizationManager.getSynchronizations().forEach(TransactionSynchronization::afterCommit);verify(rabbit,times(1)).convertAndSend(eq("events"),eq("order.deferred"),any(Map.class));}
}
